```typescript
import * as pulumi from "@pulumi/pulumi";
import * as yandex from "pulumi-yandex";

//
// Create a new Airflow Cluster.
//
const myAirflowCluster = new yandex.AirflowCluster("myAirflowCluster", {
    subnetIds: [
        yandex_vpc_subnet.a.id,
        yandex_vpc_subnet.b.id,
        yandex_vpc_subnet.d.id,
    ],
    serviceAccountId: yandex_iam_service_account["for-airflow"].id,
    adminPassword: "some-strong-password",
