        s3: {
            bucket: "bucket-for-airflow-dags",
        },
    },
    webserver: {
        count: 1,
        resource_preset_id: "c1-m4",
    },
    scheduler: {
        count: 1,
        resource_preset_id: "c1-m4",
    },
    worker: {
        min_count: 1,
        max_count: 2,
        resource_preset_id: "c1-m4",
    },
    airflowConfig: {
        api: {
            auth_backends: "airflow.api.auth.backend.basic_auth,airflow.api.auth.backend.session",
        },
    },
    pipPackages: ["dbt"],
    lockboxSecretsBackend: {
        enabled: true,
    },
    logging: {
        enabled: true,
        folder_id: _var.folder_id,
        min_level: "INFO",
    },
});
