yandex:index/backupPolicyBindings:Backup.description:
Allows management of [Yandex Cloud Attach and Detach VM](https://yandex.cloud/docs/backup/operations/policy-vm/attach-and-detach-vm).

 > Cloud Backup Provider must be activated in order to manipulate with policies.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as yandex from "pulumi-yandex";

//
// Create a new Cloud Backup Policy Binding
//
const testSa = new yandex.IamServiceAccount("testSa", {});
const testBinding = new yandex.ResourcemanagerFolderIamMember("testBinding", {
    folderId: testSa.folderId,
    role: "backup.editor",
    member: pulumi.interpolate`serviceAccount:${testSa.iamServiceAccountId}`,
});
const testBackupNetwork = new yandex.VpcNetwork("testBackupNetwork", {});
const testBackupSubnet = new yandex.VpcSubnet("testBackupSubnet", {
    zone: "ru-central1-a",
    networkId: testBackupNetwork.id,
    v4CidrBlocks: ["192.168.0.0/24"],
});
// https://yandex.cloud/ru/docs/backup/concepts/vm-connection#vm-network-access
const testBackupSecurityGroup = new yandex.VpcSecurityGroup("testBackupSecurityGroup", {
    networkId: testBackupNetwork.id,
    egresses: [
        {
            protocol: "TCP",
            fromPort: 7770,
            toPort: 7800,
            v4CidrBlocks: ["84.47.172.0/24"],
        },
        {
            protocol: "TCP",
            port: 443,
            v4CidrBlocks: [
                "213.180.204.0/24",
                "213.180.193.0/24",
                "178.176.128.0/24",
                "84.201.181.0/24",
                "84.47.172.0/24",
            ],
        },
        {
            protocol: "TCP",
            port: 80,
            v4CidrBlocks: [
                "213.180.204.0/24",
                "213.180.193.0/24",
            ],
        },
        {
            protocol: "TCP",
            port: 8443,
            v4CidrBlocks: ["84.47.172.0/24"],
        },
        {
            protocol: "TCP",
            port: 44445,
            v4CidrBlocks: ["51.250.1.0/24"],
        },
    ],
});
const ubuntu = yandex.getComputeImage({
    family: "ubuntu-2004-lts",
});
const testBackupCompute = new yandex.ComputeInstance("testBackupCompute", {
    platformId: "standard-v1",
    zone: "ru-central1-a",
    serviceAccountId: testSa.iamServiceAccountId,
    networkInterfaces: [{
        subnetId: testBackupSubnet.id,
        securityGroupIds: [testBackupSecurityGroup.id],
        nat: true,
    }],
    bootDisk: {
        initializeParams: {
            imageId: ubuntu.then(ubuntu => ubuntu.id),
        },
    },
    resources: {
        cores: 2,
