    folderId: "<your folder id (optional)>",
    imageId: data.yandex_cloud_desktops_image.image.id,
    description: "Sample description",
    desktopTemplate: {
        resources: {
            cores: 4,
            memory: 8,
            coreFraction: 100,
        },
        boot_disk: {
            initializeParams: {
                size: 24,
                type: "SSD",
            },
        },
        data_disk: {
            initializeParams: {
                size: 16,
                type: "HDD",
            },
        },
        network_interface: {
            networkId: network.id,
            subnetIds: [subnet.id],
        },
        group_config: {
            initializeParams: {
                minReadyDesktops: 1,
                maxDesktopsAmount: 5,
                desktopType: "PERSISTENT",
                members: [{
                    id: "<your id>",
