            zoneId: "example-zone-id",
            type: exampleCmCertificate.challenges.apply(challenges => challenges[range.index].dns_type).apply(x =>String(x)),
            datas: [exampleCmCertificate.challenges.apply(challenges => challenges[range.index].dns_value).apply(x =>String(x))],
            ttl: 60,
        }));
    }
});
