        labels: {
            label1: "label1-value",
            label2: "label2-value",
        },
        metadata: {
            foo: "bar",
            "ssh-keys": `ubuntu:${fs.readFileSync("~/.ssh/id_rsa.pub", "utf8")}`,
        },
        networkSettings: [{
            type: "STANDARD",
        }],
    },
    variables: {
        test_key1: "test_value1",
        test_key2: "test_value2",
    },
    scalePolicy: {
        fixedScale: {
            size: 3,
        },
    },
    allocationPolicy: {
        zones: ["ru-central1-a"],
    },
    deployPolicy: {
        maxUnavailable: 2,
        maxCreating: 2,
        maxExpansion: 2,
        maxDeleting: 2,
    },
});
