```typescript
import * as pulumi from "@pulumi/pulumi";
import * as fs from "fs";
import * as yandex from "pulumi-yandex";

//
// Create a new Compute Instance and new IAM Binding for it.
//
const vm1 = new yandex.ComputeInstance("vm1", {
    platformId: "standard-v3",
    zone: "ru-central1-a",
    resources: {
        cores: 2,
        memory: 4,
    },
    bootDisk: {
        diskId: yandex_compute_disk["boot-disk"].id,
    },
    networkInterfaces: [{
        index: 1,
        subnetId: yandex_vpc_subnet.foo.id,
    }],
    metadata: {
        foo: "bar",
        "ssh-keys": `ubuntu:${fs.readFileSync("~/.ssh/id_ed25519.pub", "utf8")}`,
    },
});
const editor = new yandex.ComputeInstanceIamBinding("editor", {
    imageId: vm1.id,
    role: "editor",
    members: ["userAccount:some_user_id"],
});
