func readFileOrPanic(path string) string {
	data, err := os.ReadFile(path)
	if err != nil {
		panic(err.Error())
	}
	return string(data)
}

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		// Create a new Compute Instance and new IAM Binding for it.
		vm1, err := yandex.NewComputeInstance(ctx, "vm1", &yandex.ComputeInstanceArgs{
			PlatformId: pulumi.String("standard-v3"),
			Zone:       pulumi.String("ru-central1-a"),
