				"foo":      pulumi.String("bar"),
				"ssh-keys": pulumi.Sprintf("ubuntu:%v", readFileOrPanic("~/.ssh/id_ed25519.pub")),
			},
		})
		if err != nil {
			return err
		}
		_, err = yandex.NewComputeInstanceIamBinding(ctx, "editor", &yandex.ComputeInstanceIamBindingArgs{
			ImageId: vm1.ID(),
