public class App {
    public static void main(String[] args) {
        Pulumi.run(App::stack);
    }

    public static void stack(Context ctx) {
        //
        // Create a new Compute Instance and new IAM Binding for it.
        //
        var vm1 = new ComputeInstance("vm1", ComputeInstanceArgs.builder()
            .platformId("standard-v3")
            .zone("ru-central1-a")
            .resources(ComputeInstanceResourcesArgs.builder()
                .cores(2)
                .memory(4.0)
                .build())
            .bootDisk(ComputeInstanceBootDiskArgs.builder()
                .diskId(yandex_compute_disk.boot-disk().id())
                .build())
            .networkInterfaces(ComputeInstanceNetworkInterfaceArgs.builder()
                .index(1)
                .subnetId(yandex_vpc_subnet.foo().id())
                .build())
            .metadata(Map.ofEntries(
                Map.entry("foo", "bar"),
                Map.entry("ssh-keys", String.format("ubuntu:%s", Files.readString(Paths.get("~/.ssh/id_ed25519.pub"))))
            ))
            .build());

        var editor = new ComputeInstanceIamBinding("editor", ComputeInstanceIamBindingArgs.builder()
            .imageId(vm1.id())
            .role("editor")
            .members("userAccount:some_user_id")
            .build());

    }
}
