    public static void stack(Context ctx) {
        // Auxiliary resources
        var fooVpcNetwork = new VpcNetwork("fooVpcNetwork");

        var fooVpcSubnet = new VpcSubnet("fooVpcSubnet", VpcSubnetArgs.builder()
            .zone("ru-central1-a")
            .networkId(fooVpcNetwork.id())
            .v4CidrBlocks("10.1.0.0/24")
            .build());

        var bar = new VpcSubnet("bar", VpcSubnetArgs.builder()
            .zone("ru-central1-b")
            .networkId(fooVpcNetwork.id())
            .v4CidrBlocks("10.2.0.0/24")
            .build());

        var baz = new VpcSubnet("baz", VpcSubnetArgs.builder()
            .zone("ru-central1-d")
            .networkId(fooVpcNetwork.id())
            .v4CidrBlocks("10.3.0.0/24")
            .build());

        //
        // Create a new MDB Sharded Clickhouse Cluster.
        //
        var myCluster = new MdbClickhouseClusterV2("myCluster", MdbClickhouseClusterV2Args.builder()
            .environment("PRODUCTION")
            .networkId(fooVpcNetwork.id())
            .clickhouse(MdbClickhouseClusterV2ClickhouseArgs.builder()
                .resources(MdbClickhouseClusterV2ClickhouseResourcesArgs.builder()
                    .resourcePresetId("s2.micro")
                    .diskTypeId("network-ssd")
                    .diskSize(16)
                    .build())
                .build())
            .zookeeper(MdbClickhouseClusterV2ZookeeperArgs.builder()
                .resources(MdbClickhouseClusterV2ZookeeperResourcesArgs.builder()
                    .resourcePresetId("s2.micro")
                    .diskTypeId("network-ssd")
                    .diskSize(10)
                    .build())
                .build())
            .shards(Map.ofEntries(
                Map.entry("shard1", MdbClickhouseClusterV2ShardsArgs.builder()
                    .weight(110)
                    .build()),
                Map.entry("shard2", MdbClickhouseClusterV2ShardsArgs.builder()
                    .weight(300)
                    .build())
            ))
            .hosts(Map.ofEntries(
                Map.entry("clickhouse-shard1-host1", MdbClickhouseClusterV2HostsArgs.builder()
                    .type("CLICKHOUSE")
                    .zone("ru-central1-a")
                    .subnetId(fooVpcSubnet.id())
                    .shardName("shard1")
                    .build()),
                Map.entry("clickhouse-shard1-host2", MdbClickhouseClusterV2HostsArgs.builder()
                    .type("CLICKHOUSE")
                    .zone("ru-central1-b")
                    .subnetId(bar.id())
                    .shardName("shard1")
                    .build()),
                Map.entry("clickhouse-shard2-host1", MdbClickhouseClusterV2HostsArgs.builder()
                    .type("CLICKHOUSE")
                    .zone("ru-central1-b")
                    .subnetId(bar.id())
                    .shardName("shard2")
                    .build()),
                Map.entry("clickhouse-shard2-host2", MdbClickhouseClusterV2HostsArgs.builder()
                    .type("CLICKHOUSE")
                    .zone("ru-central1-d")
                    .subnetId(baz.id())
                    .shardName("shard2")
                    .build())
            ))
            .shardGroups(MdbClickhouseClusterV2ShardGroupArgs.builder()
                .name("single_shard_group")
                .description("Cluster configuration that contain only shard1")
                .shardNames("shard1")
                .build())
            .cloudStorage(MdbClickhouseClusterV2CloudStorageArgs.builder()
                .enabled(false)
                .build())
            .maintenanceWindow(com.pulumi.yandex.inputs.MdbClickhouseClusterV2MaintenanceWindowArgs.builder()
                .type("ANYTIME")
                .build())
            .build());

    }
