    description: "test greenplum cluster",
    environment: "PRESTABLE",
    networkId: fooVpcNetwork.id,
    zone: "ru-central1-a",
    subnetId: fooVpcSubnet.id,
    assignPublicIp: true,
    version: "6.29",
    masterHostCount: 2,
    segmentHostCount: 5,
    segmentInHost: 1,
    masterSubcluster: {
        resources: {
            resourcePresetId: "s2.micro",
            diskSize: 24,
            diskTypeId: "network-ssd",
        },
    },
    segmentSubcluster: {
        resources: {
            resourcePresetId: "s2.micro",
            diskSize: 24,
            diskTypeId: "network-ssd",
        },
    },
    access: {
        webSql: true,
    },
    greenplumConfig: {
        max_connections: "395",
        max_slot_wal_keep_size: "1048576",
