## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as yandex from "pulumi-yandex";

// Auxiliary resources
const fooVpcNetwork = new yandex.VpcNetwork("fooVpcNetwork", {});
const myCluster = new yandex.MdbGreenplumCluster("myCluster", {
    environment: "PRESTABLE",
    networkId: fooVpcNetwork.id,
});
//
// Create a new MDB Greenplum database resource group.
//
const myResourceGroup = new yandex.MdbGreenplumResourceGroup("myResourceGroup", {
    clusterId: myCluster.id,
