yandex:index/mdbPostgresqlClusterV2:MdbP.description:
Manages a PostgreSQL cluster within the Yandex Cloud. For more information, see [the official documentation](https://cloud.yandex.com/docs/managed-postgresql/). [How to connect to the DB](https://yandex.cloud/docs/managed-postgresql/quickstart#connect). To connect, use port 6432. The port number is not configurable.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as yandex from "pulumi-yandex";

// Auxiliary resources
const fooVpcNetwork = new yandex.VpcNetwork("fooVpcNetwork", {});
const fooVpcSubnet = new yandex.VpcSubnet("fooVpcSubnet", {
    zone: "ru-central1-d",
    networkId: fooVpcNetwork.id,
    v4CidrBlocks: ["10.5.0.0/24"],
});
//
// Create a new MDB PostgreSQL Cluster (v2).
//
const myV2Cluster = new yandex.MdbPostgresqlClusterV2("myV2Cluster", {
    environment: "PRESTABLE",
    networkId: fooVpcNetwork.id,
    config: [{
        version: 17,
        resources: [{
            resourcePresetId: "s2.micro",
            diskTypeId: "network-ssd",
            diskSize: 16,
        }],
        postgresqlConfig: {
            max_connections: 395,
            enable_parallel_hash: true,
            autovacuum_vacuum_scale_factor: 0.34,
            default_transaction_isolation: "TRANSACTION_ISOLATION_READ_COMMITTED",
            shared_preload_libraries: "SHARED_PRELOAD_LIBRARIES_AUTO_EXPLAIN,SHARED_PRELOAD_LIBRARIES_PG_HINT_PLAN",
        },
    }],
    maintenanceWindow: [{
        type: "WEEKLY",
        day: "SAT",
        hour: 12,
    }],
    hosts: {
        host1d: {
            zone: "ru-central1-d",
            subnetId: fooVpcSubnet.id,
        },
    },
});
