    config: {
        password: "your_password",
        version: "7.2-valkey",
    },
    resources: {
        resource_preset_id: "hm1.nano",
        disk_size: 16,
    },
    hosts: {
        aaa: {
            zone: "ru-central1-a",
            subnetId: fooVpcSubnet.id,
        },
    },
    maintenanceWindow: {
        type: "ANYTIME",
    },
});
