    network: {
        subnet_ids: [yandex_vpc_subnet.a.id],
        security_group_ids: [yandex_vpc_security_group["spark-sg1"].id],
    },
    logging: {
        enabled: true,
        folder_id: _var.folder_id,
    },
    maintenanceWindow: {
        type: "WEEKLY",
        day: "TUE",
        hour: 10,
    },
});
